mapper.select:
SELECT 
FROM problem p FORCE INDEX (idx_problem_listing)
JOIN problem_version v ON v.id = p.current_published_version_id
WHERE p.visibility = 'PUBLIC'
  AND p.status = 'ACTIVE'
  AND v.status = 'PUBLISHED'

  AND (p.slug LIKE CONCAT('%', #{q}, '%') ESCAPE '\\'
       OR v.title LIKE CONCAT('%', #{q}, '%') ESCAPE '\\')

AND v.difficulty = #{difficulty}
AND v.code_mode = #{codeMode}

  AND EXISTS (
      SELECT 1 FROM problem_version_language pvl
      WHERE pvl.problem_version_id = v.id AND pvl.language_id = #{language}
  )



    AND JSON_CONTAINS(v.tags_json, JSON_QUOTE(#{tag}))



  AND (p.updated_at < #{cursorKey}
       OR (p.updated_at = #{cursorKey} AND p.id < UUID_TO_BIN(#{cursorId})))


  AND (p.updated_at > #{cursorKey}
       OR (p.updated_at = #{cursorKey} AND p.id > UUID_TO_BIN(#{cursorId})))


  AND (v.title > #{cursorKey}
       OR (v.title = #{cursorKey} AND p.id > UUID_TO_BIN(#{cursorId})))


  ORDER BY p.updated_at ASC, p.id ASC
  ORDER BY v.title ASC, p.id ASC
  ORDER BY p.updated_at DESC, p.id DESC

LIMIT #{limit}
